import React, { useEffect, useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { getAllMovies, changeMovieStatus, createMovie, updateMovie } from '../api/movieApi';
import MovieSearch from './MovieSearch';
import NetflixList from './netflixList';
import NetflixLen from './netflixlen';

const MovieList = () => {
    const [movies, setMovies] = useState([]);
    const [showSearch, setShowSearch] = useState(false);
    const [message, setMessage] = useState("");
    const [showModal, setShowModal] = useState(false);

    // Estado para crear/editar
    const [editingMovie, setEditingMovie] = useState(null);
    const [formData, setFormData] = useState({
        name: "",
        description: ""
    });

    const [showNetflix, setShowNetflix] = useState(false);
    const [showNetflixLen, setShowNetflixLen] = useState(false);

    const fetchMovies = async () => {
        try {
            const res = await getAllMovies();
            setMovies(res.data);
        } catch (error) {
            console.error("Error al cargar las películas:", error);
        }
    };

    const handleChangeStatus = async (id, newStatus) => {
        try {
            await changeMovieStatus(id, newStatus);
            setMovies(movies.map(m => m.id === id ? { ...m, status: newStatus } : m));
        } catch (error) {
            console.error("Error al cambiar el estado:", error);
            alert("No se pudo cambiar el estado");
        }
    };

    const handleInputChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleSave = async () => {
        if (!formData.name || !formData.description) {
            setMessage("El nombre y la descripción son obligatorios");
            return;
        }

        try {
            if (editingMovie) {
                // actualizar
                const res = await updateMovie(editingMovie.name, formData.name, formData.description);
                setMovies(movies.map(m => m.id === editingMovie.id ? res.data : m));
                setMessage(`Película "${res.data.name}" actualizada correctamente`);
            } else {
                // crear
                const res = await createMovie(formData.name, formData.description);
                setMovies([...movies, res.data]);
                setMessage(`Película "${res.data.name}" creada correctamente`);
            }
            setShowModal(false);
            setEditingMovie(null);
            setFormData({ name: "", description: "" });
        } catch (error) {
            setMessage(error.response?.data?.message || "Error al guardar la película");
        }
    };

    const handleEditMovie = (movie) => {
        setEditingMovie(movie);
        setFormData({
            name: movie.name,
            description: movie.description
        });
        setMessage("");
        setShowModal(true);
    };

    useEffect(() => {
        if (!showSearch && !showNetflix && !showNetflixLen) fetchMovies();
    }, [showSearch, showNetflix, showNetflixLen]);

    return (
        <div className="container mt-4">
            <nav className="navbar navbar-expand-lg navbar-light bg-light rounded mb-4 shadow">
                <div className="container-fluid">
                    <img
                        src="https://getbootstrap.com/docs/5.3/assets/brand/bootstrap-logo.svg"
                        alt="Logo"
                        width="30"
                        height="24"
                        className="d-inline-block align-text-top"
                    />
                    <a className="navbar-brand">Películas Frontend - React</a>

                    <div className="ms-auto d-flex gap-2">
                        {!showSearch && (
                            <button
                                className="btn btn-primary btn-sm"
                                onClick={() => {
                                    setShowSearch(true);
                                    setShowNetflix(false);
                                    setShowNetflixLen(false);
                                }}
                            >
                                Buscar Película
                            </button>
                        )}
                        {!showNetflix && (
                            <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => {
                                    setShowNetflix(true);
                                    setShowSearch(false);
                                    setShowNetflixLen(false);
                                }}
                            >
                                Lenguajes Netflix
                            </button>
                        )}
                        {!showNetflixLen && (
                            <button
                                className="btn btn-info btn-sm"
                                onClick={() => {
                                    setShowNetflixLen(true);
                                    setShowNetflix(false);
                                    setShowSearch(false);
                                }}
                            >
                                Lenguajes API
                            </button>
                        )}
                        {(showNetflix || showNetflixLen || showSearch) && (
                            <button
                                className="btn btn-success btn-sm"
                                onClick={() => {
                                    setShowSearch(false);
                                    setShowNetflix(false);
                                    setShowNetflixLen(false);
                                }}
                            >
                                Lista de Películas
                            </button>
                        )}
                        {!showSearch && !showNetflix && !showNetflixLen && (
                            <button
                                className="btn btn-success btn-sm"
                                onClick={() => {
                                    setEditingMovie(null);
                                    setFormData({ name: "", description: "" });
                                    setMessage("");
                                    setShowModal(true);
                                }}
                            >
                                Crear Película
                            </button>
                        )}
                    </div>
                </div>
            </nav>

            {showNetflix ? (
                <NetflixList />
            ) : showSearch ? (
                <MovieSearch />
            ) : showNetflixLen ? (
                <NetflixLen />
            ) : (
                <div className="table-responsive shadow rounded">
                    <table className="table table-striped table-hover table-bordered align-middle">
                        <thead className="table-dark">
                            <tr>
                                <th>Película</th>
                                <th>Descripción</th>
                                <th>Estado</th>
                                <th>Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            {movies.length > 0 ? (
                                movies.map((movie) => (
                                    <tr key={movie.id}>
                                        <td>{movie.name}</td>
                                        <td>{movie.description}</td>
                                        <td>
                                            <span className={`badge ${movie.status === 'A' ? 'bg-success' : 'bg-danger'}`}>
                                                {movie.status === 'A' ? 'Activo' : 'Inactivo'}
                                            </span>
                                        </td>
                                        <td>
                                            <button
                                                className="btn btn-sm btn-outline-primary me-2"
                                                onClick={() => handleEditMovie(movie)}
                                            >
                                                Editar
                                            </button>
                                            <button
                                                className="btn btn-sm btn-outline-warning"
                                                onClick={() => handleChangeStatus(movie.id, movie.status === 'A' ? 'I' : 'A')}
                                            >
                                                Cambiar Estado
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan="4" className="text-center">
                                        No hay películas disponibles
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}

            {/* Modal Crear/Editar Película */}
            {showModal && (
                <div className="modal show fade d-block" tabIndex="-1">
                    <div className="modal-dialog">
                        <div className="modal-content">
                            <div className="modal-header">
                                <h5 className="modal-title">
                                    {editingMovie ? "Editar Película" : "Nueva Película"}
                                </h5>
                                <button
                                    type="button"
                                    className="btn-close"
                                    onClick={() => setShowModal(false)}
                                ></button>
                            </div>
                            <div className="modal-body">
                                <div className="mb-3">
                                    <label className="form-label">Nombre</label>
                                    <input
                                        type="text"
                                        className="form-control"
                                        name="name"
                                        value={formData.name}
                                        onChange={handleInputChange}
                                    />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">Descripción</label>
                                    <input
                                        type="text"
                                        className="form-control"
                                        name="description"
                                        value={formData.description}
                                        onChange={handleInputChange}
                                    />
                                </div>
                                {message && <p className="text-danger">{message}</p>}
                            </div>
                            <div className="modal-footer">
                                <button
                                    className="btn btn-secondary"
                                    onClick={() => setShowModal(false)}
                                >
                                    Cancelar
                                </button>
                                <button
                                    className="btn btn-primary"
                                    onClick={handleSave}
                                >
                                    Guardar
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default MovieList;
